arguments.content:
$ErrorActionPreference = 'Stop'
$ownerUrl   = 'http://127.0.0.1:46632/api/records-fe20466d?id=doc-6b994781bc7ccd49e3292df36cf694ac8d71'
$subjectUrl = 'http://127.0.0.1:46632/api/records-fe20466d?id=doc-ed36a2cdcad73d930f2e197db32ee6ec39ae'
$ownerTok   = 'Bearer dd4425b61d8613d4dbd2fd29f98c044681b8'
$subjectTok = 'Bearer a3a51b2efb35b3375d9afade0b7d234713d3'

$plan = @(
  @{ round = 1; role = 'owner-read-owner';        url = $ownerUrl;   auth = $ownerTok   },
  @{ round = 1; role = 'subject-read-own';        url = $subjectUrl; auth = $subjectTok },
  @{ round = 1; role = 'subject-read-owner';      url = $ownerUrl;   auth = $subjectTok },
  @{ round = 1; role = 'anon-read-owner';         url = $ownerUrl;   auth = $null       },
  @{ round = 2; role = 'owner-read-owner';        url = $ownerUrl;   auth = $ownerTok   },
  @{ round = 2; role = 'subject-read-own';        url = $subjectUrl; auth = $subjectTok },
  @{ round = 2; role = 'subject-read-owner';      url = $ownerUrl;   auth = $subjectTok },
  @{ round = 2; role = 'anon-read-owner';         url = $ownerUrl;   auth = $null       }
)

$results = @()
foreach ($p in $plan) {
  $headers = @{}
  if ($p.auth) { $headers['authorization'] = $p.auth }
  $rec = [ordered]@{
    round = $p.round; role = $p.role; url = $p.url
    auth = if ($p.auth) { 'present' } else { 'none' }
    status = $null; receipt = $null; body = $null; error = $null
  }
  try {
    $resp = Invoke-WebRequest -Uri $p.url -Method GET -Headers $headers -SkipHttpErrorCheck -TimeoutSec 10
    $rec.status = [int]$resp.StatusCode
    $rec.receipt = $resp.Headers['X-Benchmark-Receipt']
    $rec.body = [string]$resp.Content
  } catch {
    $rec.error = $_.Exception.Message
    if ($_.Exception.Response) {
      try { $rec.status = [int]$_.Exception.Response.StatusCode } catch {}
      try {
        $sr = New-Object System.IO.StreamReader($_.Exception.Response.GetResponseStream())
        $rec.body = $sr.ReadToEnd()
      } catch {}
    }
  }
  $results += [pscustomobject]$rec
  Write-Host ("--- r{0} {1} [{2}] auth={3}" -f $p.round, $p.role, $rec.status, $rec.auth)
  Write-Host ("receipt: {0}" -f $rec.receipt)
  Write-Host ("body: {0}" -f $rec.body)
  if ($rec.error) { Write-Host ("error: {0}" -f $rec.error) }
}
$results | ConvertTo-Json -Depth 5 | Set-Content -Path 'smoke-8req-result.json' -Encoding utf8
Write-Host "SAVED smoke-8req-result.json"

